from threading import Thread


def log_to_console(log: str) -> None:
    """
    Log to console.

    :param log: log to print.
    :return: None
    """
    print(log)


def get_timestamp() -> str:
    """
    Return string with current timestamp.

    :return: String with current timestamp
    """
    ts = time.time()
    return datetime.datetime.fromtimestamp(ts).strftime("%Y-%m-%d %H:%M:%S")


def execute_command(cmd):
    """
    Execute shell command in local system.

    :param cmd: Sting with command to execute.
    :return: tuple with output and error
    """
    result = subprocess.run(cmd, capture_output=True, shell=True, text=True, check=False)
    return result.stdout, result.stderr


class ConsoleThread(Thread):
    """Class for printing data on console."""

    def __init__(self):
        """Init class."""
        self.queue = queue.Queue()  # Queue with data to send, FIFO
        Thread.__init__(self)

    def add_data(self, data):
        """
        Add data to queue.

        :param data: data to put.
        :return: None
        """
        self.queue.put(data)

    def run(self):
        """
        Loop to print data to console.

        :return: None
        """
        log_to_console(f"{get_timestamp()} Started console printing")
        while True:
            try:
                data = self.queue.get(True, 1).decode("utf-8", errors="replace")
                sys.stdout.write(data)
            except queue.Empty:
                pass  # No data. This is OK
            except UnicodeDecodeError as ude:
                log_to_console(f"{get_timestamp()} UnicodeDecodeError: '{ude}' - '{repr(ude)}'.")

    def is_finished(self):
        """
        Check if thread for object is finished.

        :return: True if thread is finished, False if the thread is running.
        """
        return False  # just to have the same interface as ClientThread for network clients


class FileLogThread(Thread):
    """Class for printing data to a file."""

    def __init__(self, filepath):
        """
        Init class.

        :param filepath: full path fo file to write.
        """
        self.queue = queue.Queue()  # Queue with data to send, FIFO
        self.filepath = filepath
        Thread.__init__(self)

    def add_data(self, data):
        """
        Add data to queue.

        :param data: data to put.
        :return: None
        """
        self.queue.put(data)

    def run(self):
        """
        Loop to write data to file.

        :return: None
        """
        log_to_console(f"[{get_timestamp()}] Started writing to file '{self.filepath}'")
        with open(self.filepath, "ab+") as file:
            need_flush = True
            while True:
                try:
                    data = self.queue.get(True, 1).decode("utf-8", errors="replace")
                    file.write(data)
                except queue.Empty:  # No data to write. It's OK
                    if need_flush:
                        file.flush()
                        need_flush = False
                except UnicodeDecodeError as ude:
                    log_to_console(f"[{get_timestamp()}] UnicodeDecodeError: '{ude}' - '{repr(ude)}'.")

    def is_finished(self):
        """
        Check if thread for object is finished.

        :return: True if thread is finished, False if the thread is running.
        """
        return False  # just to have the same interface as ClientThread for network clients


class ClientThread(Thread):
    """Class for sending data to a socket."""

    def __init__(self, clientsocket, client_address, client_id):
        """
        Init class.

        :param clientsocket: socket for client.
        :param client_address: address of client.
        :param client_id: Id
        """
        self.clientsocket = clientsocket
        self.client_address = client_address
        self.max_idle_time = 301
        self.regex_filter_compiled = None
        self.finished = False
        self.id = client_id
        self.queue = queue.Queue()  # Queue with data to send, FIFO
        self.data_recv_buffer = ""
        Thread.__init__(self)

    def add_data(self, data):
        """
        Add data to queue.

        :param data: data to put.
        :return: None
        """
        self.queue.put(data)

    def set_regex_filter(self, regex_filter):
        """
        Set filter for data.

        :param filter: String with regex filter or None to unset filter.
        :return: True if filter is set, False is filter cannot be set.
        """
        self.regex_filter_compiled = None
        if regex_filter and not regex_filter.isspace():
            try:
                self.regex_filter_compiled = re.compile(regex_filter, re.I)
                log_to_console(
                    f"[{get_timestamp()}] [{self.id}] Client connected from '{self.client_address[0]}' at port "
                    f"{self.client_address[1]} set regex filter '{regex_filter}'."
                )
            except re.error as e:
                log_to_console(
                    f"[{get_timestamp()}] [{self.id}] Client connected from '{self.client_address[0]}' at port "
                    f"{self.client_address[1]} tried to set regex filter '{regex_filter}' but it failed."
                )
                log_to_console(e)
                self.set_regex_filter(None)
                return False
        else:
            self.regex_filter_compiled = None
            log_to_console(
                f"[{get_timestamp()}] [{self.id}] Client connected from {self.client_address[0]} at port {self.client_address[1]} cleared"
                f" regex filter"
            )
        return True

    def read_data_from_socket(self, socket):
        """
        Read data from socket with command.

        :param socket: client socket.
        :return: None
        """
        buf = socket.recv(8192)
        # print ("\n  [%d] read data from socket '%s', so far in buffer '%s'\n" % (self.id, buf, self.data_recv_buffer))
        self.send_data_to_socket(buf)  # echo
        self.data_recv_buffer += buf
        for delim in ("\n", "\r"):
            while self.data_recv_buffer.find(delim) != -1:
                line, self.data_recv_buffer = self.data_recv_buffer.split(delim, 1)
                self.decode_command(line)

    def send_data_to_socket(self, data):
        """
        Send data to client.

        :param data: data to send.
        :return: True if data is sent, False if data cannot be sent.
        """
        try:
            totalsent = 0
            data_length = len(data)
            while totalsent < data_length:
                sent = self.clientsocket.send(data[totalsent:])
                if 0 == sent:
                    return False
                totalsent = totalsent + sent
        except OSError:
            return False
        return True

    def decode_command(self, line):
        """
        Decode command from client.

        :param line: line with command.
        :return: None
        """
        ok = "COMMAND OK\n"
        rejected = "COMMAND REJECTED\n"

        line = line.strip()
        m = re.search(r"set_regex_filter\s+(\S.*\S)", line)
        if m:
            if self.set_regex_filter(m.group(1)):
                self.send_data_to_socket(ok)
            else:
                self.send_data_to_socket(rejected)
        elif re.search(r"clear_regex_filter", line):
            self.set_regex_filter(None)
            self.send_data_to_socket(ok)
        else:
            log_to_console(f"[{get_timestamp()}] [{self.id}] Unknown command in line '{line}'")
            self.send_data_to_socket(rejected)

    def run(self):
        """
        Loop to send data to client.

        :return: None
        """
        data = None
        is_socket_available = True
        log_to_console(f"[{get_timestamp()}] [{self.id}] New client connected from {self.client_address[0]} at port {self.client_address[1]}")

        sockets = [self.clientsocket]
        last_transfer = time.monotonic()
        while is_socket_available:
            try:
                if (time.monotonic() - last_transfer) > self.max_idle_time:
                    is_socket_available = self.send_data_to_socket("\n")
                    last_transfer = time.monotonic()
                _, _, error_sockets = self._process_sockets(sockets)
                for _ in error_sockets:
                    break
                data = self.queue.get(True, 1)
                if self._is_data_to_send(data) is False:
                    continue
                is_socket_available = self.send_data_to_socket(data)
                last_transfer = time.monotonic()
            except queue.Empty:
                pass
            except Exception as e:
                log_to_console(e)
                break
        log_to_console(f"[{get_timestamp()}] [{self.id}] Client disconnected from {self.client_address[0]} at port {self.client_address[1]}")
        self.finished = True
        self.clientsocket.close()

    def _process_sockets(self, sockets):
        """
        Check sockets.

        :param sockets: Sockets
        :return: read sockets, write sockets and error sockets.
        """
        read_sockets, write_sockets, error_sockets = select.select(sockets, [], sockets, 0)
        for r_socket in read_sockets:
            self.read_data_from_socket(r_socket)
        return read_sockets, write_sockets, error_sockets

    def _is_data_to_send(self, data):
        """
        Check if data is to send to clients.

        :param data: Data from file.
        :return: True if data is to send to clients, False otherwise.
        """
        if self.regex_filter_compiled:
            regex_result = self.regex_filter_compiled.search(data)
            if not regex_result:
                return False  # data does not match regex filter
        return True

    def is_finished(self):
        """
        Check if thread for object is finished.

        :return: True if thread is finished, False if the thread is running.
        """
        return self.finished


class ClientsPoolThread(Thread):
    """Class for client pool thread."""

    def __init__(self, data_queue, max_no_of_clients=10):
        """
        Init class for client pool thread.

        :param data_queue: queue for data.
        :param max_no_of_clients: maximum number of clients.
        """
        self.clients = []
        self.data_queue = data_queue
        self.max_no_of_clients = max_no_of_clients
        Thread.__init__(self)

    def run(self):
        """
        Loop to add data to all clients.

        :return: None
        """
        clients_to_remove = []
        while True:
            try:
                # print ("ClientsPoolThread run", self.data_queue, " No of clients: ", len(self.clients))
                data = self.data_queue.get(True, 1)
                for client in self.clients:
                    if False is client.is_finished():
                        client.add_data(data)
                    else:
                        clients_to_remove.append(client)
                if len(clients_to_remove) > 0:
                    # log_to_console("There are clients to remove:", len(clients_to_remove))
                    for client in clients_to_remove:
                        self.clients.remove(client)
                    clients_to_remove = []

            except queue.Empty:
                pass

    def can_add_new_client(self):
        """
        Check if new client can be added.

        :return: True if client can be added, False otherwise.
        """
        return self.max_no_of_clients > len(self.clients)

    def add_client(self, client_thread):
        """
        Add client.

        :param client_thread: thread of client.
        :return: None
        """
        if self.can_add_new_client():
            client_thread.setDaemon(True)
            client_thread.start()
            self.clients.append(client_thread)
        else:
            client_thread = None


class ServerThread(Thread):
    """Class for server thread."""

    def __init__(self, port, interface, cpt):
        """
        Init class for server thread.

        :param port: server port to listen.
        :param interface: interface to listen. None for all interfaces.
        :param cpt: client pool thread.
        """
        self.port = port
        self.interface = interface
        self.cpt = cpt
        self.finish = False
        self.lastClientId = 0
        log_to_console(f"[{get_timestamp()}] Establishing server at port {self.port}")
        self.serversocket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.serversocket.bind((self.interface, self.port))
        self.serversocket.listen(5)

        Thread.__init__(self)

    def run(self):
        """
        Loop for server.

        :return: None
        """
        after_idle_sec = 1
        interval_sec = 3
        max_fails = 5
        log_to_console(f"[{get_timestamp()}] Starting for new clients")
        try:
            while True:  # Wait for new connection forever
                if self.cpt.can_add_new_client():
                    (clientsocket, address) = self.serversocket.accept()
                    self.lastClientId += 1

                    clientsocket.setsockopt(socket.SOL_SOCKET, socket.SO_KEEPALIVE, 1)
                    clientsocket.setsockopt(socket.IPPROTO_TCP, socket.TCP_KEEPIDLE, after_idle_sec)
                    clientsocket.setsockopt(socket.IPPROTO_TCP, socket.TCP_KEEPINTVL, interval_sec)
                    clientsocket.setsockopt(socket.IPPROTO_TCP, socket.TCP_KEEPCNT, max_fails)

                    ct = ClientThread(clientsocket, address, self.lastClientId)
                    self.cpt.add_client(ct)

                else:
                    time.sleep(1)
        except KeyboardInterrupt:
            log_to_console("W: interrupt received, stopping...")
        finally:
            self.serversocket.shutdown(socket.SHUT_RDWR)
            self.serversocket.close()


class TailThread(Thread):
    """Class or thread of tailing file."""

    def __init__(self, file_path, queue_to_file_content, node_id, thread_id=1, move_to_end=False, process_special_chars=False):
        """
        Init tail thread.

        :param file_path: path to file.
        :param queue_to_file_content: queue to add content of file
        :param node_id: node id of ile
        :param thread_id: id of thread
        :param move_to_end: True to move to end of file, False to start from beginning.
        :param process_special_chars: True to process special chars, False to process them as other chars.
        """
        self.file_path = file_path
        self.queue_to_file_content = queue_to_file_content
        self.node_id = node_id
        self.move_to_end = move_to_end
        self.process_special_chars = process_special_chars
        self.finish = False
        self.id = thread_id
        Thread.__init__(self)

    def run(self):
        """
        Loop to read data from file.

        :return: None
        """
        log_to_console(f"[{get_timestamp()}] [{self.id}] New thread for tail file '{self.file_path}' (node id: '{self.node_id}')")
        with open(self.file_path, "rb") as file:
            if self.move_to_end:
                file.seek(0, os.SEEK_END)
            # fd = file.fileno()
            while True:
                read_bytes = file.readline()
                # read_bytes = os.read(fd, 50)
                if read_bytes:
                    if self.process_special_chars:
                        read_bytes = read_bytes.replace("\\r\\n", "\n")
                        read_bytes = read_bytes.replace("\\r", "\n")
                        read_bytes = read_bytes.replace("\\n", "\n")
                        read_bytes = read_bytes.replace("\\t", "\t")
                    self.queue_to_file_content.put(read_bytes)
                else:
                    if True is self.finish:
                        break
                    time.sleep(0.05)

        log_to_console(f"[{get_timestamp()}] [{self.id}] Thread for tailing '{self.file_path}' is dead (node id: '{self.node_id}')")

    def finish_tailing(self):
        """
        Call to finish thread for this object.

        :return: None
        """
        self.finish = True


def find_last_file(directory, pattern):
    """
    Find last file in directory.

    :param directory: Path to directory
    :param pattern: Pattern
    :return: Tuple with name of last file and node id.
    """
    cmd = f"ls -it {directory}/{pattern} | head -1"
    last_file = ""
    node_nr = "0"
    (output, err) = execute_command(cmd)
    if err and (err.find("Broken pipe") == -1):
        log_to_console(f"Error in command execute: {err}")
    else:
        line = output.strip()
        m = re.search(r"\D*(\d+)\s+(.*)$", line)
        if m:
            node_nr = m.group(1)
            last_file = os.path.abspath(m.group(2))
    return (last_file, node_nr)


# pylint: disable-next=unused-argument
def signal_handler(signal, frame):
    """
    Handle ctrl+c.

    :param signal: Signal. Ignored
    :param frame: Frame. Ignored.
    :return: None
    """
    log_to_console(f"\n[{get_timestamp()}] You pressed Ctrl+C! Bye\n")
    sys.exit(0)


def find_syslog():
    """
    Find syslog path from ps command.

    :return: Tuple with path and mask.
    """
    path = ""
    mask = ""

    # find PATH to btslog
    btslog_path = ""

    cmd = "ps -ef | grep btslog | grep -v grep"
    (output, err) = execute_command(cmd)
    if err and (err.find("Broken pipe") == -1):
        log_to_console(f"Error in command '{cmd}' execution: '{err}'")
    else:
        line = output.strip()
        if line:
            m = re.search(r".*\s(\S+)/btslog$", line)
            if m:
                btslog_path = m.group(1)

    # find mask
    if btslog_path:
        cmd = f"grep SysLogFileTemplate {btslog_path}/configuration/btslog.ini"
        (output, err) = execute_command(cmd)
        if err and (err.find("Broken pipe") == -1):
            log_to_console(f"Error in command '{cmd}' execution: '{err}'")
        else:
            line = output.strip()
            if line:
                m = re.search(r"SysLogFileTemplate\s*=\s*(.*)\/([^/]+)$", line)
                if m:
                    path = m.group(1)
                    mask = m.group(2)
                    mask = re.sub(r"%\d+", "*", mask)
                else:
                    log_to_console(f"*** Cannot find directory and/or file mask from '{line}'")

    else:
        log_to_console(f"*** Cannot find process from command '{cmd}'")
    return (path, mask)


def main():
    """
    Start the script.

    :return: None
    """
    parser = argparse.ArgumentParser(description="Tail last file and send content to TCP socket, file or console.")
    parser.add_argument("-d", "--directory", default="", help="Directory to find file to tail.")
    parser.add_argument("-m", "--mask", default="", help="Mask of files. The last file with this mask will be tailed. For example bbv*. ")
    parser.add_argument(
        "-n", default=10, type=int, help="Number of threads for clients. At lest 10. Consoole and file also required its own thread" " if enabled."
    )
    parser.add_argument("-p", "--port", default=0, type=int, required=False, help="Number of TCP port to establish server socket")
    parser.add_argument(
        "-c", "--console", default="n", choices=["y", "n", "t", "f"], help="If y or t then print data from tailing file(s) to console."
    )
    parser.add_argument(
        "-e",
        "--end",
        default="y",
        choices=["y", "n", "t", "f"],
        help="If y or t then move to end of the first file at the beginning. Otherwise the content of" " first file to cat will be processed.",
    )
    parser.add_argument(
        "-t", "--text", default="n", choices=["y", "n", "t", "f"], help="If y or t then replace special char sets \n \r \t into special char."
    )
    parser.add_argument(
        "-o",
        "--output",
        default="",
        help="Full path to output file with all the logs (no program messages). If empty then no" " output file is created.",
    )
    args = parser.parse_args()

    path_to_file = args.directory
    mask_of_file = args.mask

    if not path_to_file or not mask_of_file:
        (path_to_file, mask_of_file) = find_syslog()

    max_no_of_clients = max(args.n, 10)
    server_port_id = args.port
    move_to_end, create_console_thread, process_special_chars = _args_translated_values(args)

    path_to_new_file = args.output

    # path_to_file = "/home/USERNAME/automation/Flexi/logs/"
    # mask_of_file = "bbv--*"
    # max_no_of_clients = 10
    # server_port_id = 2288
    # create_console_thread = False
    # path_to_new_file = "/home/USERNAME/automation/Flexi/new_file.log"

    log_to_console("\n\nParameters used for app:")
    log_to_console(f"Path with logs: '{path_to_file}'")
    log_to_console(f"Logs mask: '{mask_of_file}'")
    log_to_console(f"Max no of clients: '{max_no_of_clients}'")
    log_to_console(f"Server port: '{server_port_id}'")
    log_to_console(f"Log to console: '{create_console_thread}'")
    log_to_console(f"Store log to file: '{path_to_new_file}'\n\n")
    if 0 == server_port_id and False is create_console_thread and "" == path_to_new_file:
        log_to_console("*** Have to set at least one of the options: -c (log to console) and/or -p (server port) and/or -o (log to file).")
        return
    if not path_to_file or not mask_of_file:
        log_to_console(f"*** Path to file ('{path_to_file}') and/or file mask ('{mask_of_file}') is not set:")
        return

    signal.signal(signal.SIGINT, signal_handler)

    content_to_send = queue.Queue()  # FIFO to store data read from file

    # create thread to send data to all clients
    cpt = ClientsPoolThread(content_to_send, max_no_of_clients)
    cpt.setDaemon(True)
    cpt.start()

    # create thread for server
    if server_port_id > 0:
        st = ServerThread(server_port_id, "", cpt)
        st.setDaemon(True)
        st.start()

    if True is create_console_thread:
        cpt.add_client(ConsoleThread())
    if path_to_new_file:
        cpt.add_client(FileLogThread(path_to_new_file))
    _main_loop(path_to_file, mask_of_file, content_to_send, process_special_chars, move_to_end)


def _args_translated_values(args):
    """
    Get values from args and translate them bo boolean.

    :param args: passed arguments.
    :return: Tuple with bool values: move_to_end, create_console_thread, process_special_chars
    """
    move_to_end = False
    if args.end in ("y", "t"):
        move_to_end = True
    create_console_thread = False
    if args.console in ("y", "t"):
        create_console_thread = True
    process_special_chars = False
    if args.text in ("y", "t"):
        process_special_chars = True
    return move_to_end, create_console_thread, process_special_chars


def _main_loop(path_to_file, mask_of_file, content_to_send, process_special_chars, move_to_end):
    """
    Repeat  for tailing last file.

    :param path_to_file: Path to file.
    :param mask_of_file: Mask of file.
    :param content_to_send: content to send.
    :param process_special_chars: True to process special chars, False to treat them as other chars.
    :param move_to_end: True to move to the ned of the first file. False to process first file from the beginning.
    :return: None
    """
    # main loop to find last file
    last_file = ""
    last_node_nr = ""
    last_thread = None
    ident = 0
    while True:
        (current_last_file, current_node_nr) = find_last_file(path_to_file, mask_of_file)
        if current_last_file != last_file or current_node_nr != last_node_nr:
            last_file = current_last_file
            last_node_nr = current_node_nr
            if last_thread is not None:
                last_thread.finish_tailing()
                last_thread = None
                move_to_end = False
            ident += 1
            last_thread = TailThread(last_file, content_to_send, last_node_nr, ident, move_to_end, process_special_chars)
            last_thread.setDaemon(True)  # to exit the thread when ctrl+c is pressed
            last_thread.start()
        time.sleep(0.5)


if __name__ == "__main__":
    main()
